class TraceTests(unittest.TestCase):
    REQUEST = {
        "pipeline": {"steps": [
            {"op": "filter", "where": "x > 0"},
            {"op": "branch", "branches": [
                {"when": "x > 5", "steps": [{"op": "map", "as": "big", "expr": "true"}]},
                {"when": "x > 100", "steps": [{"op": "limit", "n": 1}]},
                {"when": "otherwise", "steps": []},
            ]},
            {"op": "LIMIT", "n": 2},
        ]},
        "dataset": [{"x": 1}, {"x": 7}, {"x": -1}, {"x": 3}],
    }

    def test_spec_example(self):
        code, out = run(self.REQUEST, "--execute", "--trace")
        self.assertEqual(code, 0)
        self.assertEqual(out, {
            "status": "ok",
            "data": [{"x": 7, "big": True}, {"x": 1}],
            "metrics": {"rows_in": 4, "rows_out": 2},
            "trace": [
                {"path": "pipeline.steps[0]", "op": "filter", "rows_in": 4, "rows_out": 3},
                {"path": "pipeline.steps[1]", "op": "branch", "rows_in": 3, "rows_out": 3},
                {"path": "pipeline.steps[1].branches[0].steps[0]", "op": "map", "rows_in": 1, "rows_out": 1},
                {"path": "pipeline.steps[1].branches[1].steps[0]", "op": "limit", "rows_in": 0, "rows_out": 0},
                {"path": "pipeline.steps[2]", "op": "limit", "rows_in": 3, "rows_out": 2},
            ],
        })

    def test_nested_branch_order(self):
        inner = {"op": "branch", "branches": [{"when": "otherwise", "steps": [{"op": "limit", "n": 1}]}]}
        request = {"pipeline": {"steps": [
            {"op": "branch", "branches": [
                {"when": "otherwise", "steps": [inner, {"op": "map", "as": "y", "expr": "1"}]},
            ]},
        ]}, "dataset": [{"x": 1}, {"x": 2}]}
        _, out = run(request, "--execute", "--trace")
        self.assertEqual([(e["path"], e["rows_in"], e["rows_out"]) for e in out["trace"]], [
            ("pipeline.steps[0]", 2, 1),
            ("pipeline.steps[0].branches[0].steps[0]", 2, 1),
            ("pipeline.steps[0].branches[0].steps[0].branches[0].steps[0]", 2, 1),
            ("pipeline.steps[0].branches[0].steps[1]", 1, 1),
        ])

    def test_trace_ignored_without_execute(self):
        self.assertEqual(run(self.REQUEST, "--trace"), run(self.REQUEST))

    def test_no_trace_without_flag_or_on_error(self):
        _, out = run(self.REQUEST, "--execute")
        self.assertNotIn("trace", out)
        bad = {"pipeline": {"steps": [{"op": "select", "columns": ["y"]}]}, "dataset": [{"x": 1}]}
        self.assertEqual(run(bad, "--execute", "--trace"), run(bad, "--execute"))


